html-styling.durable-css:
.nexus-center { text-align: center; }
.nexus-muted  { color: var(--text-muted); font-size: 0.9em; }
.nexus-accent { color: var(--text-accent); font-weight: 600; }

.nexus-pullquote {
  border-left: 3px solid var(--text-accent);
  padding: 0.5em 1em;
  margin: 1.5em 0;
  font-style: italic;
}

.nexus-dropcap {
  float: left;
  font-size: 3em;
  line-height: 0.8;
  padding-right: 0.08em;
}

.nexus-rule {
  border: none;
  border-top: 1px solid var(--background-modifier-border);
  margin: 2em 0;
}

.nexus-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

.nexus-card {
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  padding: 12px 16px;
  margin: 1em 0;
}

.markdown-preview-view p:dir(rtl) { unicode-bidi: plaintext; }

@media print {
  .nexus-grid { display: block; }
  .nexus-card { break-inside: avoid; }
}

@media (max-width: 480px) {
  .nexus-grid { grid-template-columns: 1fr; }
}
